const mode = String($env.WEBHOOK_VERIFY_SIGNATURE || 'false').toLowerCase();
const passthrough = (verified, m) => [{ json: Object.assign({ verified, mode: m }, $input.first().json) }];
if (mode === 'false') { return passthrough(true, 'disabled'); }
const secret = $env.META_APP_SECRET || '';
const headers = $input.first().json.headers || {};
const signature = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';
const rawBody = JSON.stringify($input.first().json.body);
if (!secret) { return passthrough(false, 'missing_secret'); }
const run = async () => { try { const encoder = new TextEncoder(); const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']); const sig = await crypto.subtle.sign('HMAC', key, encoder.encode(rawBody)); const hex = Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join(''); return passthrough(signature === 'sha256=' + hex, 'enabled'); } catch (e) { return passthrough(false, 'crypto_unavailable'); } };
return run();

const payload = $input.first().json;
const businessPhone = ($env.WHATSAPP_BUSINESS_PHONE || '').replace(/\D/g, '');
for (const entry of payload.body.entry || payload.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    if (value.messages && value.messages.length > 0) {
      const msg = value.messages[0];
      const from = String(msg.from || '').replace(/\D/g, '');
      if (businessPhone && from === businessPhone) { throw new Error('IGNORADO: mensaje del propio negocio'); }
      const hasText = msg.text && msg.text.body;
      if (msg.type && msg.type !== 'text' && !hasText) { throw new Error('IGNORADO: tipo no soportado (' + msg.type + ')'); }
      if (!hasText) { throw new Error('IGNORADO: sin texto'); }
      return [{ json: { valid: true, contact_phone: from, message_text: String(msg.text.body).slice(0, 2000), message_id: msg.id || '', timestamp: msg.timestamp || '', type: msg.type || 'text' } }];
    }
    if (value.statuses && value.statuses.length > 0) { throw new Error('IGNORADO: status'); }
  }
}
throw new Error('IGNORADO: sin mensaje');

// Encuentra la fila del contacto en cualquier forma de respuesta (array, body, anidado).
const findRow = (x) => {
  if (Array.isArray(x)) { for (const it of x) { const f = findRow(it); if (f) return f; } return null; }
  if (x && typeof x === 'object') {
    if (x.id && (x.telefono || x.tenant_id)) return x;
    for (const v of Object.values(x)) { const f = findRow(v); if (f) return f; }
  }
  return null;
};
const row = findRow($json) || {};
if (!row.id) { throw new Error('UPSERT-FALLO: ' + JSON.stringify($json).slice(0, 300)); }
return [{ json: { contacto_id: row.id, tenant_id: row.tenant_id || null } }];

let historyRows = [];
try { historyRows = $('Obtener Historial').all().map(i => i.json).flat(1).filter(r => r && typeof r === 'object' && !Array.isArray(r)); } catch (e) {}
const contents = historyRows.map(h => ({ role: h.role === 'assistant' ? 'model' : 'user', parts: [{ text: h.content }] }));
contents.push({ role: 'user', parts: [{ text: $('Normalizar Mensaje').item.json.message_text }] });
const systemInstruction = $env.SYSTEM_PROMPT || 'Eres el asistente virtual del negocio. Responde corto y claro.';
return [{ json: { model: 'gemini-flash-latest', contents, system_instruction: { parts: [{ text: systemInstruction }] } } }];

const text = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts[0].text) || '';
const clean = text.replace(/\[DERIVAR\]/gi, '').replace(/\[LEAD[^\]]*\]/gi, '').trim().slice(0, 4000);
return [{ json: { raw: text, clean, needs_human: /\[DERIVAR\]/i.test(text), lead_marker: (text.match(/\[LEAD ([^\]]*)\]/i) || [null, ''])[1] } }];
